<script setup lang="ts">import { Head, Link } from '@inertiajs/vue3'; import AuthenticatedLayout from '../../../Layouts/AuthenticatedLayout.vue'; defineProps<{ customer:{id:number;name:string;customer_number:string}; ticket:any; canOperate:boolean }>(); const label = (value:string) => ({ open:'待处理', waiting_customer:'等待客户', waiting_internal:'内部处理中', resolved:'已解决', closed:'已关闭', low:'低', normal:'普通', high:'高', urgent:'紧急', manual:'手工录入' } as Record<string,string>)[value] ?? value</script>
<template><Head title="支持工单 · BYL ERP" /><AuthenticatedLayout title="客户支持工单" :breadcrumbs="['BYL ERP','客户',customer.name,'支持工单']"><div class="erp-form-page"><div class="erp-form-content"><div class="erp-form-header-row"><div><p class="erp-form-subtitle">{{ customer.customer_number }}</p><h1 class="erp-form-title">{{ ticket.ticket_number }}</h1></div><div class="erp-form-header-actions page-header-actions"><Link class="erp-btn erp-btn-secondary" :href="`/customers/library/${customer.id}`">返回客户</Link><Link v-if="canOperate" class="erp-btn erp-btn-primary" :href="`/customers/library/${customer.id}/support-tickets/${ticket.id}/edit`">编辑</Link></div></div><article class="erp-form-card"><h2 class="erp-form-card-title">{{ ticket.subject }}</h2><dl class="ticket-details"><dt>状态</dt><dd>{{ label(ticket.status) }}</dd><dt>优先级</dt><dd>{{ label(ticket.priority) }}</dd><dt>来源</dt><dd>{{ label(ticket.source_type) }}</dd><dt>负责人</dt><dd>{{ ticket.assignee?.name ?? '—' }}</dd><dt>最后活动</dt><dd>{{ ticket.last_activity_at ?? '—' }}</dd></dl><p class="ticket-description">{{ ticket.description || '暂无描述' }}</p></article></div></div></AuthenticatedLayout></template><style scoped>.ticket-details{display:grid;grid-template-columns:120px 1fr;gap:10px;margin:0 0 20px}.ticket-details dt{color:#7A8C94}.ticket-details dd{margin:0;color:#142126}.ticket-description{white-space:pre-wrap;color:#344B53}</style>
